import{_ as e,o as a,c as r,ag as n}from"./chunks/framework.DTisvaUJ.js";const h=JSON.parse('{"title":"プライバシー","description":"Mutelinkが外部へ送るデータとPC内に保存する情報を説明。音声認識・翻訳・利用状況の送信・不具合報告で送られる内容を確認できます。","frontmatter":{"description":"Mutelinkが外部へ送るデータとPC内に保存する情報を説明。音声認識・翻訳・利用状況の送信・不具合報告で送られる内容を確認できます。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"ja_JP"}],["meta",{"property":"og:title","content":"プライバシー | Mutelink"}],["meta",{"property":"og:description","content":"Mutelinkが外部へ送るデータとPC内に保存する情報を説明。音声認識・翻訳・利用状況の送信・不具合報告で送られる内容を確認できます。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"プライバシー | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelinkが外部へ送るデータとPC内に保存する情報を説明。音声認識・翻訳・利用状況の送信・不具合報告で送られる内容を確認できます。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/about/privacy"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/about/privacy"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/about/privacy"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/about/privacy"}]]},"headers":[],"relativePath":"about/privacy.md","filePath":"about/privacy.md"}'),i={name:"about/privacy.md"};function o(l,t,s,u,d,p){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="プライバシー" tabindex="-1">プライバシー <a class="header-anchor" href="#プライバシー" aria-label="Permalink to &quot;プライバシー&quot;">​</a></h1><p>Mutelinkが、外部に送るデータについてです。</p><h2 id="外部に送られるデータ" tabindex="-1">外部に送られるデータ <a class="header-anchor" href="#外部に送られるデータ" aria-label="Permalink to &quot;外部に送られるデータ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>場面</th><th>送られるもの</th><th>送り先</th></tr></thead><tbody><tr><td>音声認識で、クラウドのエンジンを選んだとき</td><td>マイクの音声</td><td>Microsoft または Google</td></tr><tr><td>翻訳で、Azure Translatorを使ったとき</td><td>翻訳する文</td><td>Microsoft(自分のキー)</td></tr><tr><td>聞こえた声で、Googleを選んだとき</td><td>相手の声</td><td>Google</td></tr><tr><td>聞こえた声を、チャットボックスに出したとき</td><td>相手の発言(とその訳)</td><td>VRChat(インスタンスにいる全員に見えます)</td></tr><tr><td>利用状況の送信を許可したとき</td><td>匿名の利用状況(下の説明)</td><td>開発者が運営するサーバー(Cloudflare)</td></tr><tr><td>「不具合・要望を送る」で送信したとき</td><td>書いた内容と、選んだ添付(下の説明)</td><td>開発者が運営するサーバー(Cloudflare)と、開発者のDiscord</td></tr><tr><td>ダウンロード、アップデートの確認</td><td>通信に必要な情報だけ</td><td>各配布元</td></tr></tbody></table><p>次のものは、PCの中だけで動き、外には出ません。</p><ul><li>このPCで動く音声認識(Parakeet、Haas-ja、Qwen3-ASR、Whisper turbo)</li><li>読み上げ(VOICEVOX、Irodori-TTS、Qwen3-TTS)</li><li>このPCで動く翻訳(PLaMo、TranslateGemma)</li><li>VRキーボードのかな漢字変換、拼音の変換</li></ul><p>聞こえた声は、このPCで認識すると、相手の声はPCの外に出ません。音は、認識が終わるとすぐに捨てられ、保存されません。Googleを選ぶと、相手の声がGoogleのサーバーに送られます。相手に知らせるなど、使い方に気をつけてください。</p><p>VRの中のパネル(聞こえた声、自分のチャットボックス)は、自分にだけ見えます。ただし、配信ソフトがVRの画面をそのまま映しているときは、パネルも映ります。</p><h2 id="利用状況の送信" tabindex="-1">利用状況の送信 <a class="header-anchor" href="#利用状況の送信" aria-label="Permalink to &quot;利用状況の送信&quot;">​</a></h2><p>Mutelinkの改善のために、<strong>ご本人が許可した場合に限り</strong>、匿名の利用状況を、月に1回だけ送ります。クイックセットアップの最後で確認します。許可しなければ、何も送りません。設定 &gt; そのほか &gt; アプリについて で、いつでも切り替えられ、次に送る内容も確認できます。</p><ul><li><strong>送る内容</strong>: アプリのバージョン、PCの構成(OS、CPU、GPU、メモリの量)、機能の利用回数(起動、VRでの起動、エンジン別の認識・読み上げ・翻訳、読み上げや翻訳のエラー、VR入力方式別の操作、チャットボックス送信)、設定の値(言語別エンジン、翻訳優先順位、入力方式、使い方、ボタン配置の変更有無など)、有料機能の有無</li><li><strong>送らない内容</strong>: 話した内容、認識したテキスト、入力した文章、声の音声、語尾の文言、テンプレート、除外ワード、履歴、デバイスの名前、APIキー、登録した声の名前、氏名・連絡先</li><li><strong>送り先</strong>: 開発者が運営する、Cloudflareのサーバーです。IPアドレスは保存しません</li><li><strong>目的</strong>: どの機能がどのくらい使われているか、どんなPCで動いているかを知り、改善の優先順位を決めるためです</li><li><strong>匿名ID</strong>: アプリが作るランダムな番号です。個人とは結び付きません。設定から、いつでも作り直せます</li></ul><h2 id="不具合・要望の送信" tabindex="-1">不具合・要望の送信 <a class="header-anchor" href="#不具合・要望の送信" aria-label="Permalink to &quot;不具合・要望の送信&quot;">​</a></h2><p>設定 &gt; そのほか &gt; アプリについて の「不具合・要望を送る」から、開発者にメッセージを送れます(匿名)。<strong>ボタンを押したときだけ</strong>送られます。送る前に、実際に送られる内容を確認できます。</p><ul><li><strong>必ず送る内容</strong>: 種類(不具合・要望・その他)と、書いた文章です。連絡先は、返信が欲しいときだけ、任意で書きます</li><li><strong>選んだときだけ送る内容</strong>: アプリのバージョンとPCの情報(OS、CPU、メモリ、GPU、VRAM)、動作の記録(ログ)、画像1枚です。ログと画像は、初期状態ではオフです</li><li><strong>ログに入らないもの</strong>: 話した内容や、入力した文章を含む行は、送るときに除きます。パスに含まれるユーザー名は伏せます</li><li><strong>画像</strong>: 画面に映っているもの(通知、名前、ファイル名など)が、そのまま写ります。画像は、開発者のDiscordに通知されるだけで、サーバーには保存しません</li><li><strong>扱い</strong>: IPアドレスは保存しません。利用状況の報告とも結び付けません。名前や住所などの個人情報は、書かないでください</li></ul><h2 id="pcの中に保存されるデータ" tabindex="-1">PCの中に保存されるデータ <a class="header-anchor" href="#pcの中に保存されるデータ" aria-label="Permalink to &quot;PCの中に保存されるデータ&quot;">​</a></h2><p>ダウンロードしたモデルやキャラクター、登録した声(録音そのものは保存せず、声の特徴だけを保存します)、VR背景の画像、ライセンスのファイル、設定、翻訳した文字数の記録は、PCの中に保存されます。</p><p>新しくインストールした場合は、<code>%LOCALAPPDATA%\\com.utyujinn.mutelink</code> の中にあります。古いバージョンから使い続けている場合は、Mutelinkをインストールしたフォルダの中に残っていることがあります。</p><p>Azure Translatorのキーは、このPCの設定にだけ保存されます。</p>',18)])])}const c=e(i,[["render",o]]);export{h as __pageData,c as default};
